<script setup lang="ts">
import { computed, defineAsyncComponent, onBeforeUnmount, onMounted, provide, ref, watch } from 'vue'
import { zh_cn } from '@nuxt/ui/locale'
import type { MenuItem, PageId, SampleData } from './types'
import { cancelLeave, navigate, notify, resolveLeave, state, switchRole } from './state'
import Icon from './components/Icon.vue'
import FusionBusiness from './fusion/FusionBusiness.vue'
import { fusionDataKey } from './fusion/context'
import { initializeFusionIdentity, fusionPaths } from './fusion/identity'
import fusionRouter from '../legacy-src/router'
import { protectEdit } from './state'
const PlatformPage = defineAsyncComponent(() => import('./components/PlatformPage.vue'))
const rolePicker = ref(false), activeResult = ref(0)
const data = ref<SampleData>(), error = ref(''), query = ref(''), menuQuery = ref(''), samplesOpen = ref(false)
provide(fusionDataKey, data)
const pages: { id: PageId; title: string; icon: string; subtitle: string; number: string }[] = [{ id: 'plans', title: '生产计划', icon: 'plans', subtitle: '计划列表、筛选、详情与编辑', number: '01' }, { id: 'canvas', title: '工序规划画布', icon: 'canvas', subtitle: '真实工序、投入产出与草稿编辑', number: '02' }, { id: 'analytics', title: '数据分析', icon: 'chart', subtitle: '成本构成、计划状态与数据依据', number: '03' }, { id: 'ai', title: 'AI 工作台', icon: 'ai', subtitle: '快照分析、预览确认与回读', number: '04' }, { id: 'platform', title: '平台治理', icon: 'shield', subtitle: '真实工厂目录、选厂配置与角色边界', number: '05' }]
const current = computed(() => pages.find(p => p.id === state.page) || pages[0])
const navigation = computed(() => pages.filter(p => state.role === 'platform' ? p.id === 'platform' : p.id !== 'platform'))
const allMenus = computed(() => (data.value?.menu[state.role] || []).filter(p => `${p.title} ${p.path}`.toLowerCase().includes(menuQuery.value.toLowerCase())))
const results = computed(() => [...pages.filter(p => `${p.title} ${p.subtitle}`.includes(query.value)).map(p => ({ title: p.title, hint: '新版交互样板', page: p.id, path: '' })), ...(data.value?.menu[state.role] || []).filter(p => `${p.title} ${p.path}`.includes(query.value)).slice(0, 15).map(p => ({ title: p.title, hint: '原版完整页面', page: null, path: p.path }))])
const originalPath = computed(() => data.value?.originalPaths[state.page] || '/dashboard')
const iframe = computed(() => `${originalPath.value}?prototype=original&v5role=${state.role}`)
const compareVersion = computed(() => state.role === 'platform' ? 'platform_admin' : 'f006_admin')
const changes: Record<PageId, { title: string; before: string; after: string }[]> = {
  plans: [{ title: '信息组织', before: '计划字段集中在长表格', after: '按状态筛选，产品与编号合并层级，详情渐进展开' }, { title: '视觉', before: '沿用原版组件与局部样式', after: '统一品牌色、字体、边框、密度与状态标签' }, { title: '编辑', before: '保留原版业务表单', after: 'Element Plus 密集表格和表单保留，统一外观和抽屉布局' }, { title: '数据', before: '原账号计划记录', after: '源字段完整保留，计划编辑和分析共用本机工作区' }],
  canvas: [{ title: '工作区', before: '原产品工序配置页面', after: '独立画布、工序库和按需属性面板' }, { title: '操作', before: '查看原版已有功能', after: '拖动、连线、撤销、适应视图、恢复与保存草稿' }, { title: '依据', before: '原版保存的完整 Workflow 定义与版本', after: '直接使用11份真实画布定义，保留原料、半成品、工序、成品和全部配置' }],
  analytics: [{ title: '口径', before: '原经营报表部分为空', after: '保留空态，同时单独展示已有生产和成本数据' }, { title: '图表', before: '保留 ECharts 与源结果', after: '统一图表主题、图例、留白、口径和缺失值表达' }, { title: '追溯', before: '数据分散于不同模块', after: '从结论进入统计行和源字段，不虚构销售指标' }],
  ai: [{ title: 'AI入口', before: '原AI问答与工作台', after: '对话、工作范围与受控操作并列呈现' }, { title: '信任', before: '保留原账号执行响应', after: '区分源执行记录与本地规则演示，显示来源和能力边界' }, { title: '操作', before: '原有后端流程继续保留', after: '演示预览→确认→本机保存→回读，可真实停止流式呈现' }],
  platform: [{ title: '职责', before: '原平台侧包含工厂菜单', after: '默认只呈现平台治理，工厂业务进入独立账号工作区' }, { title: '数据', before: '原平台7家工厂目录', after: '沿用同一目录与原字段，不把F006记录套给其他工厂' }, { title: '配置', before: '平台与工厂配置上下文混合', after: '选厂对象明确展示，配额编辑保存为本机草稿' }]
}
function pageTarget(page: PageId, sample: SampleData) { const base=fusionPaths[page] || '/production/plans'; return page === 'canvas' && sample.fusion?.defaultOwnerId ? { path: base, query: { productTypeId: sample.fusion.defaultOwnerId } } : base }
async function load() { error.value = ''; try { const response = await fetch('/__v5/data'); if (!response.ok) throw new Error('本地数据尚未就绪，请从样板启动入口打开。'); const sample: SampleData = await response.json(); const params = new URLSearchParams(location.search), page = params.get('page'); if (pages.some(p => p.id === page)) { state.page = page as PageId; state.role = page === 'platform' ? 'platform' : 'factory' }; await initializeFusionIdentity(state.role); if (state.role === 'factory') await fusionRouter.replace(pageTarget(state.page,sample)); data.value = sample } catch (e) { error.value = e instanceof Error ? e.message : '样板加载失败' } }
function openOriginal(path = originalPath.value) { const role = state.role === 'platform' ? 18841 : 18842; const target = new URL(`http://127.0.0.1:${role}${path}`); target.searchParams.set('prototype', 'original'); window.open(target.href, '_blank', 'noopener'); state.menusOpen = false; state.searchOpen = false }
function selectSearch(item: { page: PageId | null; path: string }) { if (item.page) navigate(item.page); else openOriginal(item.path) }
function toggleNavigation() { if (matchMedia('(max-width: 760px)').matches) state.mobileMenu = !state.mobileMenu; else state.sidebarCollapsed = !state.sidebarCollapsed }
function keyboard(e: KeyboardEvent) {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); state.searchOpen = !state.searchOpen; return }
  if (e.key === 'Escape') { state.mobileMenu = false; rolePicker.value = false }
  if (!state.searchOpen) return
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); activeResult.value = (activeResult.value + (e.key === 'ArrowDown' ? 1 : -1) + results.value.length) % Math.max(1, results.value.length); document.querySelector('.command-results .keyboard-active')?.scrollIntoView({ block: 'nearest' }) }
  if (e.key === 'Enter' && results.value[activeResult.value]) { e.preventDefault(); selectSearch(results.value[activeResult.value]) }
}
watch(query, () => activeResult.value = 0)
watch(() => [state.page, state.role] as const, async ([page, role]) => { if (!data.value) return; await initializeFusionIdentity(role); if (role === 'factory' && fusionPaths[page]) { const result = await fusionRouter.push(pageTarget(page,data.value!)); if (result) { const matched = Object.entries(fusionPaths).find(([, value]) => value === fusionRouter.currentRoute.value.path); if (matched) state.page = matched[0] as PageId } } }, {flush:'post'})
watch(() => [state.page, state.role], () => { history.replaceState({}, '', '/samples/?page=' + state.page + '&role=' + state.role) })
onMounted(() => { load(); document.addEventListener('keydown', keyboard) })
onBeforeUnmount(() => document.removeEventListener('keydown', keyboard))
</script>

<template>
  <UApp :locale="zh_cn"><div v-if="error" class="load-screen"><Icon name="info" :size="36" /><h1>样板暂未就绪</h1><p>{{ error }}</p><UButton @click="load">重新加载</UButton></div><div v-else-if="!data" class="load-screen"><div class="loading-logo">C</div><p>正在打开 Cretas 交互样板…</p></div><div v-else :class="['cretas-app', { 'compare-mode': state.compare, 'is-dense': state.dense, 'sidebar-collapsed': state.sidebarCollapsed, 'mobile-menu-open': state.mobileMenu }]">
    <button v-if="state.mobileMenu" class="sidebar-scrim" aria-label="关闭导航遮罩" @click="state.mobileMenu = false" /><aside class="app-sidebar"><button class="sidebar-close-mobile icon-button" aria-label="关闭导航" @click="state.mobileMenu = false"><Icon name="close" /></button><a class="brand" href="/samples/"><span class="brand-symbol"><svg width="22" height="23" viewBox="0 0 24 24" fill="none"><path d="M19 5 12 2 4 6v12l8 4 7-3v-5h-7v4l-4-2V8l4-2 7 3V5Z" fill="currentColor" /></svg></span><span>CRETAS<small>白垩纪 · 管理工作台</small></span></a><button class="workspace-picker" :aria-expanded="rolePicker" aria-label="选择管理工作区" @click="rolePicker = !rolePicker"><span class="workspace-icon"><Icon :name="state.role === 'factory' ? 'factory' : 'shield'" :size="18" /></span><span><strong>{{ state.role === 'factory' ? data.factoryName : '平台治理工作区' }}</strong><small>{{ state.role === 'factory' ? 'F006 · 工厂超级管理员' : 'platform_admin · 平台管理员' }}</small></span><Icon name="down" :size="14" /></button>
      <div v-if="rolePicker" class="workspace-role-menu"><strong>切换工作区</strong><button @click="switchRole('factory'); rolePicker = false"><Icon name="factory" /><span>工厂超级管理员<small>F006 · 生产、工序与经营</small></span><Icon v-if="state.role === 'factory'" name="check" :size="16" /></button><button @click="switchRole('platform'); rolePicker = false"><Icon name="shield" /><span>平台管理员<small>租户治理与平台配置</small></span><Icon v-if="state.role === 'platform'" name="check" :size="16" /></button></div><div class="nav-section">{{ state.role === 'factory' ? '生产与经营' : '平台管理' }}</div><nav aria-label="样板导航"><button v-for="p in navigation" :key="p.id" :aria-label="p.title" :title="p.title" :aria-current="state.page === p.id ? 'page' : undefined" :class="['nav-item', { active: state.page === p.id }]" @click="navigate(p.id)"><Icon :name="p.icon" :size="19" /><span>{{ p.title }}</span><small>{{ p.number }}</small></button></nav><div class="nav-section">设计预览</div><button class="nav-item" aria-label="全部五个样板" title="全部五个样板" @click="samplesOpen = true"><Icon name="grid" :size="19" /><span>全部五个样板</span><span class="nav-count">5</span></button><button class="nav-item" aria-label="原版全部菜单" title="原版全部菜单" @click="state.menusOpen = true"><Icon name="layers" :size="19" /><span>原版全部菜单</span><Icon name="external" :size="13" /></button><button class="nav-item" aria-label="本页设计变化" title="本页设计变化" @click="state.changesOpen = true"><Icon name="compare" :size="19" /><span>本页设计变化</span></button>
      <button class="sidebar-collapse nav-item" :aria-label="state.sidebarCollapsed ? '展开侧边栏' : '收起侧边栏'" :title="state.sidebarCollapsed ? '展开侧边栏' : '收起侧边栏'" @click="state.sidebarCollapsed = !state.sidebarCollapsed"><Icon name="panel" :size="19" /><span>收起导航</span><kbd>[</kbd></button><div class="sidebar-bottom"><div class="sample-status"><i class="dot blue" /><span>交互样板 · 本机草稿</span><button aria-label="交互样板说明" @click="samplesOpen = true"><Icon name="info" :size="14" /></button></div><div class="sidebar-profile"><span class="avatar">{{ state.role === 'factory' ? '张' : 'P' }}</span><div><strong>{{ state.role === 'factory' ? data.userName : '平台管理员' }}</strong><small>{{ compareVersion }}</small></div><button aria-label="打开界面设置" @click="state.settingsOpen = true"><Icon name="settings" :size="17" /></button></div></div>
    </aside>
    <div class="app-shell"><header class="app-topbar"><div class="breadcrumbs"><button class="icon-button nav-toggle" :aria-label="state.sidebarCollapsed ? '展开导航' : '切换导航'" @click="toggleNavigation()"><Icon name="menu" :size="20" /></button><Icon :name="state.role === 'platform' ? 'shield' : 'factory'" :size="16" /><span>{{ state.role === 'platform' ? '平台工作区' : '工厂工作区' }}</span><Icon name="chevron" :size="12" /><strong>{{ current.title }}</strong></div><div class="top-actions"><button class="command-trigger" aria-label="搜索菜单与页面" @click="state.searchOpen = true"><Icon name="search" :size="16" /><span>搜索菜单与页面</span><kbd>Ctrl K</kbd></button><button class="icon-button" aria-label="调整动效与密度" @click="state.settingsOpen = true"><Icon name="settings" :size="19" /></button><button class="icon-button" aria-label="查看数据时间" @click="notify('当前使用 '+data.snapshotUpdatedAt.slice(0,10)+' 账号快照，不代表实时数据。')"><Icon name="bell" :size="19" /><i class="notification-dot" /></button><span class="top-avatar">{{ state.role === 'factory' ? '张' : 'P' }}</span></div></header>
      <div class="preview-bar"><div><span class="preview-label">交互样板 {{ current.number }} / 05</span><span class="preview-divider" /><span class="preview-caption">{{ state.compare ? '左侧原版 · 右侧新方案 · 同一账号快照' : '五页交互体验 · 编辑保存到本机' }}</span></div><div class="preview-controls"><button :class="{ active: !state.compare }" @click="state.compare = false"><Icon name="grid" :size="14" />新方案</button><button :class="{ active: state.compare }" @click="state.compare = true"><Icon name="compare" :size="14" />左右对照</button><button @click="openOriginal()">原版独立打开<Icon name="external" :size="13" /></button></div></div>
      <main :class="['page-workspace', { 'comparison-board': state.compare }]">
        <section v-if="state.compare" class="compare-pane original-pane"><div class="comparison-label"><span><i class="dot gray" />原版 Vue 页面</span><small>{{ compareVersion }} · 此窗只读预览</small></div><iframe :key="state.page + state.role" :src="iframe" :title="'原版' + current.title" referrerpolicy="same-origin" /></section>
        <section :class="{ 'compare-pane modern-pane': state.compare }"><div v-if="state.compare" class="comparison-label"><span><i class="dot blue" />新方案 · 同一账号数据</span><button @click="state.changesOpen = true">查看变化<Icon name="arrow" :size="12" /></button></div><div class="page-content"><Transition name="page" mode="out-in"><div :key="state.role" class="page-transition-root"><FusionBusiness v-if="state.role === 'factory'" :data="data" /><PlatformPage v-else :data="data" /></div></Transition></div></section>
      </main><footer class="workspace-footer"><span>F006 / platform_admin 账号快照 · {{ data.snapshotUpdatedAt.slice(0, 10) }} · 原版内容保持保留</span><button @click="state.menusOpen = true">完整菜单与数据入口<Icon name="external" :size="12" /></button></footer>
    </div><Transition name="toast"><div v-if="state.message" class="feedback-toast" role="status"><Icon name="check" :size="18" />{{ state.message }}<button aria-label="关闭提示" @click="state.message = ''"><Icon name="close" :size="14" /></button></div></Transition>
  </div>

  <UModal v-model:open="state.searchOpen" title="搜索页面" description="搜索五个新版样板和当前角色保留的原版菜单" :ui="{ content: 'max-w-2xl' }"><template #body><div class="search-field command-search"><Icon name="search" :size="19" /><UInput v-model="query" autofocus placeholder="输入菜单、页面或业务关键词…" aria-label="全局搜索" /></div><div class="command-hint">↑ ↓ 选择 · Enter 打开 · Esc 关闭</div><div class="command-results"><button v-for="(item, i) in results" :key="i" :class="{ 'keyboard-active': activeResult === i }" @mouseenter="activeResult = i" @click="selectSearch(item)"><span class="small-square"><Icon :name="item.page ? 'grid' : 'file'" :size="16" /></span><span>{{ item.title }}<small>{{ item.hint }}</small></span><Icon name="arrow" :size="16" /></button><p v-if="!results.length" class="empty-block">没有匹配结果，试试“生产”或“分析”。</p></div></template></UModal>
  <UModal v-model:open="samplesOpen" title="五个新版交互样板" description="先比较真实业务页面的设计和操作，再扩展完整菜单" :ui="{ content: 'max-w-3xl' }"><template #body><div class="sample-cards"><button v-for="p in pages" :key="p.id" @click="navigate(p.id); samplesOpen = false"><span class="sample-card-number">{{ p.number }}</span><span class="sample-icon"><Icon :name="p.icon" :size="25" /></span><strong>{{ p.title }}</strong><p>{{ p.subtitle }}</p><span>{{ p.id === 'platform' ? '平台管理员' : '工厂超级管理员' }}<Icon name="arrow" :size="15" /></span></button></div><div class="source-note"><Icon name="info" /><div>本轮只制作这五个样板。原版完整菜单和账号快照仍可独立操作，样板没有覆盖未展示的模块，也不将其计为已优化。</div></div></template></UModal>
  <USlideover v-model:open="state.settingsOpen" title="界面与动效" description="体验不同密度与动画档位；偏好保存在本机" :ui="{ content: 'max-w-sm' }"><template #body><div class="settings-section"><h3>动效档位</h3><div class="motion-options"><button v-for="option in [{ key: 'standard', label: '标准', text: '页面和面板自然过渡' }, { key: 'light', label: '轻量', text: '减少移动，缩短过渡' }, { key: 'off', label: '关闭', text: '即时切换，减少动态效果' }]" :key="option.key" :class="{ active: state.motion === option.key }" @click="state.motion = option.key"><span>{{ option.label }}<small>{{ option.text }}</small></span><Icon v-if="state.motion === option.key" name="check" :size="17" /></button></div><label class="duration-control">标准过渡时长 <b>{{ state.duration }} ms</b><input v-model.number="state.duration" type="range" min="120" max="400" step="20" aria-label="动效过渡时长" /></label><div class="motion-demo"><div :key="state.duration + state.motion" class="motion-demo-block" /><span>统一的进入与反馈节奏</span></div></div><div class="settings-section"><h3>文字大小</h3><div class="segmented"><button :class="{ active: state.textSize === 'standard' }" @click="state.textSize = 'standard'">标准字号</button><button :class="{ active: state.textSize === 'large' }" @click="state.textSize = 'large'">大字号</button></div><h3 class="setting-gap">业务表格密度</h3><div class="segmented"><button :class="{ active: !state.dense }" @click="state.dense = false">标准</button><button :class="{ active: state.dense }" @click="state.dense = true">紧凑</button></div><p class="muted">数据密集时减少行高，保留字号和操作命中区域。</p></div></template></USlideover>
  <USlideover v-model:open="state.changesOpen" :title="current.title + ' · 设计变化'" description="对照同一账号原版页面，说明本页改变了什么" :ui="{ content: 'max-w-md' }"><template #body><section v-for="c in changes[state.page]" :key="c.title" class="change-section"><h3>{{ c.title }}</h3><small>原版</small><p>{{ c.before }}</p><small class="new-label">新方案</small><p>{{ c.after }}</p></section><UButton block color="neutral" variant="outline" @click="state.compare = true; state.changesOpen = false">打开左右对照<Icon name="compare" :size="16" /></UButton></template></USlideover>
  <UModal v-model:open="state.menusOpen" title="原版完整菜单与账号数据" description="以下保留原有菜单入口，独立打开原版；不将它们计入本轮五页优化" :ui="{ content: 'max-w-3xl' }"><template #body><div class="menu-catalog-top"><div class="segmented"><button :class="{ active: state.role === 'factory' }" @click="switchRole('factory')">工厂超级管理员</button><button :class="{ active: state.role === 'platform' }" @click="switchRole('platform')">平台管理员</button></div><UInput v-model="menuQuery" placeholder="搜索原版菜单…" aria-label="搜索原版菜单" /></div><p class="muted">{{ allMenus.length }} 个原版页面／详情入口 · 沿用 V3 完整目录</p><div class="full-menu-grid"><button v-for="m in allMenus" :key="m.path" @click="openOriginal(m.path)"><Icon name="file" :size="15" /><span>{{ m.title }}<small>{{ m.path }}</small></span><Icon name="external" :size="12" /></button></div><a class="all-original-link" href="http://127.0.0.1:18840/" target="_blank" rel="noopener">打开 V3 完整原版／优化版目录<Icon name="external" :size="14" /></a></template></UModal>
  <UModal :open="state.leaveOpen" @update:open="(v: boolean) => { if (!v) cancelLeave() }" title="有未保存的修改" description="选择保存本机草稿后离开，或放弃本次未保存的修改。"><template #body><p class="leave-explanation">当前编辑尚未保存。保存后可以刷新页面继续查看；原账号数据不受影响。</p></template><template #footer><div class="leave-actions"><UButton color="neutral" variant="outline" @click="cancelLeave">继续编辑</UButton><UButton color="error" variant="ghost" @click="resolveLeave(false)">放弃修改并离开</UButton><UButton @click="resolveLeave(true)">保存草稿并离开</UButton></div></template></UModal>
  </UApp>
</template>
